return [{
  json: {
    // Ziel des Digests: Ihre Telegram-ID (Privatchat mit dem Bot), @Kanal oder -100... (Bot muss Kanal-Admin sein)
    chatId: '135656943',
    // Empfänger von Meldungen über defekte Feeds; '' = keine Meldungen
    adminChatId: '',
    digestTitle: 'Nachrichten-Digest',
    lookbackHours: 26,
    maxItemsPerSource: 20,
    maxItemsTotal: 150,
    topN: 10,
    // 'gemini' oder 'claude'
    provider: 'gemini',
    geminiModel: 'gemini-3.6-flash',
    // Wird genutzt, wenn geminiModel nach allen Versuchen nicht antwortet (z. B. 503 bei Überlastung)
    geminiFallbackModel: 'gemini-3.5-flash-lite',
    claudeModel: 'claude-opus-5-5',
    claudeEffort: 'medium',
    seenRetentionDays: 30,
  },
}];

return $input.all()
  .map((i) => i.json)
  .filter((r) => r.url)
  .sort((a, b) => a.id - b.id)
  .map((r) => ({ json: { url: r.url, title: r.title || r.url } }));

const cfg = $('Config').first().json;
const since = Date.now() - cfg.lookbackHours * 3600 * 1000;

const ENTITIES = { amp: '&', lt: '<', gt: '>', quot: '"', apos: "'", nbsp: ' ', laquo: '«', raquo: '»', mdash: '—', ndash: '–', hellip: '…' };
const clean = (s) => String(s || '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&(#x[0-9a-f]+|#\d+|\w+);/gi, (all, e) => {
    if (e[0] === '#') {
      const code = e[1].toLowerCase() === 'x' ? parseInt(e.slice(2), 16) : parseInt(e.slice(1), 10);
      return code >= 0 && code <= 0x10ffff ? String.fromCodePoint(code) : all;
    }
    return ENTITIES[e.toLowerCase()] ?? all;
  })
  .replace(/\s+/g, ' ')
  .trim();

const failed = new Set();
const bySource = new Map();
const seenLinks = new Set();

$input.all().forEach((item, idx) => {
  let src = {};
  try {
    src = $('Prepare sources').itemMatching(idx).json;
  } catch (e) {}
  const j = item.json;
  if (j.error) {
    failed.add(src.url || '?');
    return;
  }
  const link = String(j.link || j.guid || '').trim();
  const title = clean(j.title);
  if (!/^https?:\/\//i.test(link) || !title || seenLinks.has(link)) return;

  const ts = Date.parse(j.isoDate || j.pubDate || '');
  if (!Number.isNaN(ts) && ts < since) return;
  seenLinks.add(link);

  const key = src.url || '?';
  if (!bySource.has(key)) bySource.set(key, []);
  bySource.get(key).push({
    link,
    title: title.slice(0, 300),
    snippet: clean(j.contentSnippet || j.content || j.summary).slice(0, 400),
    source: src.title || key,
    feed: key,
    ts: Number.isNaN(ts) ? null : ts,
  });
});

return [{ json: { items: [...bySource.values()].flat(), failed: [...failed] } }];

const cfg = $('Config').first().json;
const { items } = $('Normalize').first().json;
const seen = new Set($input.all().map((i) => i.json.link).filter(Boolean));

const newest = (a, b) => (b.ts ?? 0) - (a.ts ?? 0);
const perSource = new Map();
for (const it of items) {
  if (seen.has(it.link)) continue;
  if (!perSource.has(it.feed)) perSource.set(it.feed, []);
  perSource.get(it.feed).push(it);
}

const candidates = [...perSource.values()]
  .flatMap((list) => list.sort(newest).slice(0, cfg.maxItemsPerSource))
  .sort(newest)
  .slice(0, cfg.maxItemsTotal);

if (candidates.length === 0) return [];
return [{ json: { candidates } }];

const cfg = $('Config').first().json;
const { candidates } = $input.first().json;

const fmtDate = (ts) => (ts ? new Date(ts).toISOString().slice(0, 16).replace('T', ' ') + ' UTC' : 'ohne Datum');
const list = candidates
  .map((c, i) => `[${i + 1}] ${c.source} · ${fmtDate(c.ts)}\n${c.title}${c.snippet ? `\n${c.snippet}` : ''}`)
  .join('\n\n');

const system = [
  'Du bist Redakteur eines Telegram-Nachrichtenkanals. Aus einer Liste aktueller Medienbeiträge stellst du einen kurzen Digest des Wichtigsten zusammen.',
  '',
  'Auswahl:',
  '- Relevanz: Folgen für viele Menschen, Wirtschaft, Politik, Technologie, Wissenschaft; neue Fakten statt Meinungen und Nacherzählungen.',
  '- Dieselbe Geschichte aus mehreren Quellen ist ein Punkt; nimm den informativsten Beitrag. Berichten mehrere Medien darüber, spricht das für Relevanz.',
  '- Keine Werbung, Horoskope, Unterhaltungs-Kleinkram, inhaltslose Ankündigungen oder Clickbait.',
  `- Höchstens ${cfg.topN} Punkte; gibt es weniger Relevantes, dann weniger. Reihenfolge: das Wichtigste zuerst.`,
  '',
  'Schreibweise (auf Deutsch, unabhängig von der Sprache der Quelle):',
  '- title: kurze, informative Überschrift in eigenen Worten, ohne Anführungszeichen um die ganze Überschrift und ohne Emojis.',
  '- summary: 1–2 Sätze: worum es geht und warum es wichtig ist. Nur Fakten aus dem Beitrag, nichts hinzudichten.',
  '- intro: ein Satz zum Gesamtbild des Tages.',
  '- id: die Nummer des Beitrags aus der Liste in eckigen Klammern.',
].join('\n');

const schema = {
  type: 'object',
  properties: {
    intro: { type: 'string' },
    items: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'integer' },
          title: { type: 'string' },
          summary: { type: 'string' },
        },
        required: ['id', 'title', 'summary'],
        additionalProperties: false,
      },
    },
  },
  required: ['intro', 'items'],
  additionalProperties: false,
};

const user = `Beiträge (${candidates.length}):\n\n${list}`;

if (cfg.provider === 'gemini') {
  const { additionalProperties, ...itemSchema } = schema.properties.items.items;
  const geminiSchema = {
    type: 'object',
    properties: { ...schema.properties, items: { type: 'array', items: itemSchema } },
    required: schema.required,
  };
  return [{
    json: {
      provider: 'gemini',
      body: {
        systemInstruction: { parts: [{ text: system }] },
        contents: [{ role: 'user', parts: [{ text: user }] }],
        generationConfig: {
          responseMimeType: 'application/json',
          responseJsonSchema: geminiSchema,
          maxOutputTokens: 16000,
        },
      },
    },
  }];
}

return [{
  json: {
    provider: 'claude',
    body: {
      model: cfg.claudeModel,
      max_tokens: 16000,
      output_config: { effort: cfg.claudeEffort, format: { type: 'json_schema', schema } },
      fallbacks: 'default',
      system,
      messages: [{ role: 'user', content: user }],
    },
  },
}];

const cfg = $('Config').first().json;
const { candidates } = $('Filter new').first().json;
const res = $input.first().json;

function claudeText(r) {
  if (r.stop_reason === 'refusal') {
    throw new Error(`Claude hat die Antwort verweigert: ${JSON.stringify(r.stop_details)}`);
  }
  if (r.stop_reason === 'max_tokens') throw new Error('Antwort von Claude wurde bei max_tokens abgeschnitten');
  return (r.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('');
}

function geminiText(r) {
  const cand = (r.candidates || [])[0];
  if (!cand) {
    throw new Error(`Gemini hat keine Antwort geliefert: ${JSON.stringify(r.promptFeedback || r).slice(0, 500)}`);
  }
  if (cand.finishReason && cand.finishReason !== 'STOP') {
    throw new Error(`Gemini hat mit finishReason=${cand.finishReason} abgebrochen`);
  }
  return (cand.content?.parts || []).filter((p) => !p.thought && p.text).map((p) => p.text).join('');
}

const text = cfg.provider === 'gemini' ? geminiText(res) : claudeText(res);
let data;
try {
  data = JSON.parse(text);
} catch (e) {
  throw new Error(`Das Modell hat kein JSON geliefert: ${text.slice(0, 500)}`);
}

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const escAttr = (s) => esc(s).replace(/"/g, '&quot;');

const used = new Set();
const picks = [];
for (const it of data.items || []) {
  const c = candidates[it.id - 1];
  if (!c || used.has(it.id)) continue;
  used.add(it.id);
  picks.push({ ...it, c });
  if (picks.length >= cfg.topN) break;
}
if (picks.length === 0) return [];

const date = $now.setLocale('de').toFormat('d. MMMM yyyy');
const blocks = [
  `<b>📰 ${esc(cfg.digestTitle)} — ${esc(date)}</b>`,
  ...(data.intro ? [`<i>${esc(data.intro)}</i>`] : []),
  ...picks.map((p, i) =>
    `${i + 1}. <b>${esc(p.title)}</b>\n${esc(p.summary)}\n<a href="${escAttr(p.c.link)}">${esc(p.c.source)}</a>`),
];

const LIMIT = 4000;
const posts = [];
let cur = '';
for (const block of blocks) {
  if (cur && cur.length + 2 + block.length > LIMIT) {
    posts.push(cur);
    cur = block;
  } else {
    cur = cur ? `${cur}\n\n${block}` : block;
  }
}
if (cur) posts.push(cur);

return posts.map((text) => ({ json: { chatId: cfg.chatId, text } }));

const cfg = $('Config').first().json;
const { failed } = $input.first().json;
if (!cfg.adminChatId || failed.length === 0) return [];
return [{ json: { chatId: cfg.adminChatId, text: `⚠️ Folgende Feeds konnten nicht gelesen werden:\n${failed.join('\n')}` } }];
